--- a/service/src/main/java/com/huawei/ncedatacubeplus/datasmartcubeservice/impl/IntelligentTemplateDelegateImpl.java
+++ b/service/src/main/java/com/huawei/ncedatacubeplus/datasmartcubeservice/impl/IntelligentTemplateDelegateImpl.java
@@ -70,9 +70,21 @@ public class IntelligentTemplateDelegateImpl implements IntelligentTemplateDeleg
         LogResult logResult = LogResult.FAILURE;
         try {
             ReportTemplate template = input.getTemplate();
+            // 检查模板状态是否为已发布
+            if ("Deployed".equals(template.getStatus())) {
+                LOGGER.error("Template is already deployed, cannot modify directly.");
+                ErrorCodeUtil.throwBadReqExp(CheckErrorCode.TEMPLATE_HAS_PUBLISH);
+            }
+            // 检查模板名称是否已存在
+            ReportTemplatePO existingTemplate = reportTemplateDao.selectByTemplateName(template.getBasicInfo().getName());
+            if (existingTemplate != null) {
+                LOGGER.error("Template name already exists: {}", template.getBasicInfo().getName());
+                ErrorCodeUtil.throwBadReqExp(CheckErrorCode.TEMPLATE_NAME_EXISTS);
+            }
             ReportTemplatePO reportTemplatePO = ConvertUtils.reportTemplateDTO2PO(template);
             reportTemplatePO.setCreator(HttpContextUtil.getUserName(context));
             reportTemplatePO.setModifier(HttpContextUtil.getUserName(context));
+            reportTemplateDao.selectByTemplateId(reportTemplatePO.getTemplateId());
             ReportTemplate response = ConvertUtils.reportTemplatePO2Response(reportTemplatePO);
             reportTemplateDao.insert(reportTemplatePO);
             logResult = LogResult.SUCCESSFUL;
@@ -183,6 +195,14 @@ public class IntelligentTemplateDelegateImpl implements IntelligentTemplateDeleg
         LogResult logResult = LogResult.FAILURE;
         try {
             ReportTemplate template = input.getTemplate();
+            // 检查模板名称是否已存在（排除当前模板）
+            String newTemplateName = template.getBasicInfo().getName();
+            ReportTemplatePO templateWithSameName = reportTemplateDao.selectByTemplateName(newTemplateName);
+            if (templateWithSameName != null && !templateWithSameName.getTemplateId().equals(templateId)) {
+                LOGGER.error("Template name already exists: {}", newTemplateName);
+                ErrorCodeUtil.throwBadReqExp(CheckErrorCode.TEMPLATE_NAME_EXISTS);
+            }
+            
             ReportTemplatePO reportTemplatePO = ConvertUtils.reportTemplateDTO2PO(template);
             ReportTemplate response = ConvertUtils.reportTemplatePO2Response(reportTemplatePO);
             reportTemplatePO.setModifier(HttpContextUtil.getUserName(context));
@@ -246,6 +266,9 @@ public class IntelligentTemplateDelegateImpl implements IntelligentTemplateDeleg
             throw new NCEAgentException();
         }
         ReportTemplatePO responsePO = reportTemplateDao.selectByTemplateId(templateId);
+        if (responsePO == null) {
+            return null;
+        }
         return ConvertUtils.reportTemplatePO2Response(responsePO);
     }
 }
